       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
    ).bind(
      crypto.randomUUID(),
      options.clientId,
      storedSecret,
      0,
      1,
      "public",
      JSON.stringify(options.scopes),
