    expect(getSetupRedirect("/", 404, false)).toBeUndefined();
    expect(getSetupRedirect("/sign-in", 404, false)).toBeUndefined();
    expect(getSetupRedirect("/setup", 404, false)).toBe("/sign-in");
  });
});

