import { LinkProvider } from "@cloudflare/kumo";
import type { QueryClient } from "@tanstack/react-query";
import { QueryClientProvider } from "@tanstack/react-query";
import { createRootRouteWithContext, Outlet, redirect } from "@tanstack/react-router";

import { AppLink } from "../components/app-link";
import { RootDocument } from "../components/root-document";
import { getSetupRedirect } from "../lib/setup-routing";
import { getTreaty } from "./api.$";
import "../styles/app.css";

export const Route = createRootRouteWithContext<{ queryClient: QueryClient }>()({
  beforeLoad: async ({ location }) => {
    const response = await getTreaty()
      .setup.status.get()
      .catch(() => null);
    if (!response) return;

    const redirectTo = getSetupRedirect(
      location.pathname,
      response.status,
      response.data?.available === true,
    );
    if (redirectTo) throw redirect({ to: redirectTo });
  },
  head: () => ({
    meta: [
      { charSet: "utf-8" },
      { name: "viewport", content: "width=device-width, initial-scale=1" },
      { name: "description", content: "Shui identity control plane" },
    ],
    title: "Shui | identity control plane",
  }),
  component: RootComponent,
});

function RootComponent() {
  const { queryClient } = Route.useRouteContext();

  return (
    <RootDocument>
      <QueryClientProvider client={queryClient}>
        <LinkProvider component={AppLink}>
          <div className="min-h-screen bg-kumo-canvas text-kumo-default">
            <main>
              <Outlet />
            </main>
          </div>
        </LinkProvider>
      </QueryClientProvider>
    </RootDocument>
  );
}
  return betterAuth({
    appName: "Shui",
    basePath: "/api/auth",
    baseURL: environment.BETTER_AUTH_URL,
    database: drizzleAdapter(db, {
      provider: "sqlite",
      schema: authSchema,
      transaction: false,
    }),
    disabledPaths: ["/token"],
    emailAndPassword: {
      enabled: true,
      autoSignIn: false,
      disableSignUp: true,
      requireEmailVerification: false,
      revokeSessionsOnPasswordReset: true,
      sendResetPassword: async ({ user, url, token }) => {
        await deliverEmail(environment, {
          email: user.email,
          kind: "password-reset",
          token,
          url,
        });
        await recordAuthAudit(db, "auth.password_reset_requested", user.id, {});
      },
    },
    emailVerification: {
      autoSignInAfterVerification: false,
      sendOnSignIn: false,
      sendOnSignUp: false,
      sendVerificationEmail: async ({ user, url, token }) => {
        await deliverEmail(environment, {
          email: user.email,
          kind: "verification",
          token,
          url,
        });
        await recordAuthAudit(db, "auth.verification_sent", user.id, {});
      },
    },
    plugins: [
      jwt(),
      oauthProvider({
        allowDynamicClientRegistration: false,
        allowUnauthenticatedClientRegistration: false,
